(1128660, 139220, 25017, '<td valign="top">what a lovely, emotion captured, I love this entry has a real feeling of yesteryear, well done</td>', 'what a lovely, emotion captured, I love this entry has a real feeling of yesteryear, well done', '2005-01-24 07:28:06.000000', NULL, 1),
(1128661, 139080, 25017, '<td valign="top">I like the feeling of the runners turning a bend, like the whole scen and feeling, looks good in b&amp;w too</td>', 'I like the feeling of the runners turning a bend, like the whole scen and feeling, looks good in b&w too', '2005-01-24 07:29:02.000000', NULL, 1),
