(1128668, 138671, 3306, '<td valign="top">On Stage shots are difficult to get because of the lighting. You have done very well here. Good one</td>', 'On Stage shots are difficult to get because of the lighting. You have done very well here. Good one', '2005-01-24 07:32:07.000000', NULL, 1),
(1128672, 138260, 19952, '<td valign="top">This is such a outstanding picture that tells a beautiful, emotional story - a real accomplishment.</td>', 'This is such a outstanding picture that tells a beautiful, emotional story - a real accomplishment.', '2005-01-24 07:35:59.000000', NULL, 1),
(1128673, 139326, 3306, '<td valign="top">I like everything about this picture except that in my opinion it appears that you have over manipulated it. The composition is excellent, The shadows are interesting and it absolutely satisfies the challenge. There is just something about the hands that doesn''t look real. This would look great on heavy  mat textured poster paper.</td>', 'I like everything about this picture except that in my opinion it appears that you have over manipulated it. The composition is excellent, The shadows are interesting and it absolutely satisfies the challenge. There is just something about the hands that doesn''t look real. This would look great on heavy  mat textured poster paper.', '2005-01-24 07:36:22.000000', NULL, 1),
(1128677, 138338, 3306, '<td valign="top">This one would have been a good entry in the Where''s Waldo or Feet Challenges. I like it but I would have suggested that it might look better if you cropped out the left side a little to eliminate the snow and reflection in the water. It is a little distracting. Good eye for an interesting picture.</td>', 'This one would have been a good entry in the Where''s Waldo or Feet Challenges. I like it but I would have suggested that it might look better if you cropped out the left side a little to eliminate the snow and reflection in the water. It is a little distracting. Good eye for an interesting picture.', '2005-01-24 07:40:30.000000', NULL, 1),
(1128678, 139189, 3306, '<td valign="top">I like everything about your picture. The placement, the pose, the lighting and the grainy appearance. You might get knocked down in this challenge because some might consider that it is showing the subjects face. Great job though.</td>', 'I like everything about your picture. The placement, the pose, the lighting and the grainy appearance. You might get knocked down in this challenge because some might consider that it is showing the subjects face. Great job though.', '2005-01-24 07:42:55.000000', NULL, 1),
(1128679, 138781, 3306, '<td valign="top">Ominous in subject, lighting and compostion. Good job.</td>', 'Ominous in subject, lighting and compostion. Good job.', '2005-01-24 07:44:05.000000', NULL, 1),
(1128682, 139190, 3306, '<td valign="top">If we are forced to show someone''s back there should be an interesting scene to look at, a contrast, or a story to be told. You have done it well here. Good job.</td>', 'If we are forced to show someone''s back there should be an interesting scene to look at, a contrast, or a story to be told. You have done it well here. Good job.', '2005-01-24 07:47:11.000000', NULL, 1),
(1128689, 139315, 3306, '<td valign="top">You know, I don''t give many 2''s but unfortunately this one fits into that category, but I feel I owe you an explanation. This picture might have passed as a reasonable attempt at impressionism but I find the over saturation and the fact that it appears rotated 180 degrees unappealing. From just a photographic point of view, it is out of focus, poorly lit and unattractive. Finally, it does not satisfy the challenge. I am sorry to be so negative, but hopefully this is a learning experience.</td>', 'You know, I don''t give many 2''s but unfortunately this one fits into that category, but I feel I owe you an explanation. This picture might have passed as a reasonable attempt at impressionism but I find the over saturation and the fact that it appears rotated 180 degrees unappealing. From just a photographic point of view, it is out of focus, poorly lit and unattractive. Finally, it does not satisfy the challenge. I am sorry to be so negative, but hopefully this is a learning experience.', '2005-01-24 07:55:10.000000', NULL, 1),
(1128692, 138431, 3306, '<td valign="top">This picture difinitely has something interesting to offer the viewer. An interesting subject, excellent shadows, good composition and satisfies the challenge. Only one suggestion would be to crop out the top half of the picture just above the last clock and since this is an advanced editing challenge, you could have cloned out the feet at the top after cloning. Great job though.</td>', 'This picture difinitely has something interesting to offer the viewer. An interesting subject, excellent shadows, good composition and satisfies the challenge. Only one suggestion would be to crop out the top half of the picture just above the last clock and since this is an advanced editing challenge, you could have cloned out the feet at the top after cloning. Great job though.', '2005-01-24 07:58:48.000000', NULL, 1),
(1128693, 139247, 3306, '<td valign="top">The lighting really makes this picture. Good job.</td>', 'The lighting really makes this picture. Good job.', '2005-01-24 07:59:49.000000', NULL, 1),
(1128696, 138280, 25787, '<td valign="top">would be better if subject wasn''t centered in photo</td>', 'would be better if subject wasn''t centered in photo', '2005-01-24 08:00:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1128701, 139100, 17291, '<td valign="top">Love this picture.</td>', 'Love this picture.', '2005-01-24 08:10:11.000000', NULL, 1),
(1128712, 138338, 18191, '<td valign="top">I think that cropping out that rock in the bottom right corner would help bring the viewer to the legs and subject a little bit better.</td>', 'I think that cropping out that rock in the bottom right corner would help bring the viewer to the legs and subject a little bit better.', '2005-01-24 08:19:40.000000', NULL, 1),
(1128718, 139229, 18191, '<td valign="top">How original! Great stuff and good lighting. I don''t understand it quite yet, but it''s beautiful! 10.</td>', 'How original! Great stuff and good lighting. I don''t understand it quite yet, but it''s beautiful! 10.', '2005-01-24 08:22:35.000000', NULL, 1),
(1128723, 138431, 18191, '<td valign="top">Holy cow! This shot a beauty. A gerat angle with the perfect use of backlighting. The time theme is great too, I''m really digging it. To be really picky, I would either crop a little bit off the top, or clone out the little white specks in the shadows (one at the top of the image and one on the upper middle right) just for the fact that those areas do not necessarily add to the image, and anything taken away from this great shot would be a crime! This is beautiful work --- straight into favs.</td>', 'Holy cow! This shot a beauty. A gerat angle with the perfect use of backlighting. The time theme is great too, I''m really digging it. To be really picky, I would either crop a little bit off the top, or clone out the little white specks in the shadows (one at the top of the image and one on the upper middle right) just for the fact that those areas do not necessarily add to the image, and anything taken away from this great shot would be a crime! This is beautiful work --- straight into favs.', '2005-01-24 08:26:47.000000', NULL, 1),
(1128724, 138781, 18191, '<td valign="top">I think I know who this is --- and great lighting! These shots always freak me out, but it is very photogenic. Graat job that deserves a high score.</td>', 'I think I know who this is --- and great lighting! These shots always freak me out, but it is very photogenic. Graat job that deserves a high score.', '2005-01-24 08:27:51.000000', NULL, 1),
(1128732, 139190, 18191, '<td valign="top">Okay, this is one of my top shots of this challenge. The story portrayed here is great and the technicality, superb. It is nearly pinsharp throughout the entire image and the composition is spot-on. There is great detail and interesting elements in both the foreground and the background, so this is a shot that someone could look at for a very long time. As far as any help I could offer, I would start by rotating this about 2 degrees to the left so that it is a little more straightened out. Although I personally like it how it is, some may prefer a horizontal flip as it is easier on most people''s eyes to "read" an image from the left going to the right. Either way, we are all humbled in your brilliance, and keep up the good work --- keep inspiring!</td>', 'Okay, this is one of my top shots of this challenge. The story portrayed here is great and the technicality, superb. It is nearly pinsharp throughout the entire image and the composition is spot-on. There is great detail and interesting elements in both the foreground and the background, so this is a shot that someone could look at for a very long time. As far as any help I could offer, I would start by rotating this about 2 degrees to the left so that it is a little more straightened out. Although I personally like it how it is, some may prefer a horizontal flip as it is easier on most people''s eyes to "read" an image from the left going to the right. Either way, we are all humbled in your brilliance, and keep up the good work --- keep inspiring!', '2005-01-24 08:33:40.000000', NULL, 1),
(1128735, 139077, 31203, '<td valign="top">Must be playing Pinochle.  Nice idea fora photo.</td>', 'Must be playing Pinochle.  Nice idea fora photo.', '2005-01-24 08:35:41.000000', NULL, 1),
