INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1134134, 138814, 29948, '<td valign="top">this is very sad. i like it very much!</td>', 'this is very sad. i like it very much!', '2005-01-26 19:44:51.000000', NULL, 1),
(1134136, 138847, 29948, '<td valign="top">creepy, but cool</td>', 'creepy, but cool', '2005-01-26 19:45:36.000000', NULL, 1),
(1134206, 138847, 13113, '<td valign="top">This is so cool! I like it! 10!</td>', 'This is so cool! I like it! 10!', '2005-01-26 20:15:19.000000', NULL, 1),
(1134270, 139304, 17103, '<td valign="top">There is something so strange about the composition of this shot with the tree smack-dab in the middle like that, and what an odd looking tree it is.  But I really like the overall feeling with the completely slate gray sky, and the tree and lampposts looking like they''re completely covered in frost -- 8.</td>', 'There is something so strange about the composition of this shot with the tree smack-dab in the middle like that, and what an odd looking tree it is.  But I really like the overall feeling with the completely slate gray sky, and the tree and lampposts looking like they''re completely covered in frost -- 8.', '2005-01-26 20:48:27.000000', NULL, 1),
(1134275, 138443, 17103, '<td valign="top">Very nice!  8</td>', 'Very nice!  8', '2005-01-26 20:50:17.000000', NULL, 1),
(1134280, 139080, 17103, '<td valign="top">Beautiful light you captured in the runners'' breath - 8</td>', 'Beautiful light you captured in the runners'' breath - 8', '2005-01-26 20:51:28.000000', NULL, 1),
(1134286, 138833, 24982, '<td valign="top">I''m not sure what that thing around his shoulders is. But it is a cool effect for this challenge to have the face blurred like that... Kind of reminds me of "the ring"</td>', 'I''m not sure what that thing around his shoulders is. But it is a cool effect for this challenge to have the face blurred like that... Kind of reminds me of "the ring"', '2005-01-26 20:55:06.000000', NULL, 1),
(1134287, 138736, 24982, '<td valign="top">Almost looks like a painting</td>', 'Almost looks like a painting', '2005-01-26 20:55:26.000000', NULL, 1),
(1134292, 139343, 24982, '<td valign="top">Seems like the hair comes out of nowhere, so maybe a larger crop area would have been better.</td>', 'Seems like the hair comes out of nowhere, so maybe a larger crop area would have been better.', '2005-01-26 20:59:53.000000', NULL, 1),
(1134322, 138763, 24982, '<td valign="top">They should put this pictures in their brochure... wherever this is</td>', 'They should put this pictures in their brochure... wherever this is', '2005-01-26 21:23:04.000000', NULL, 1),
(1134327, 139290, 22479, '<td valign="top">Ha, this is quite funny. The artificial pose of the person makes this one look a bit too hokey.</td>', 'Ha, this is quite funny. The artificial pose of the person makes this one look a bit too hokey.', '2005-01-26 21:29:46.000000', NULL, 1),
(1134333, 138737, 10658, '<td valign="top">I really like the stopped motion here, it''s very crisp.  Actually the more I look at this one the more I like everything about it.  No faces anywhere so it really does fit the challenge perfectly (unlike many of the photos I''ve seen so far).  Excellent! :)</td>', 'I really like the stopped motion here, it''s very crisp.  Actually the more I look at this one the more I like everything about it.  No faces anywhere so it really does fit the challenge perfectly (unlike many of the photos I''ve seen so far).  Excellent! :)', '2005-01-26 21:38:44.000000', NULL, 1),
(1134334, 138313, 10658, '<td valign="top">I''m sure I''m not the first to say this, but that''s creepy!  Interesting take on the challenge, I like the effect.</td>', 'I''m sure I''m not the first to say this, but that''s creepy!  Interesting take on the challenge, I like the effect.', '2005-01-26 21:40:23.000000', NULL, 1),
(1134337, 138916, 10658, '<td valign="top">The colors are phenomenal, composition is really nice, great photo for this challenge.  Overall I think it''s wonderful, it should definitely place highly :)</td>', 'The colors are phenomenal, composition is really nice, great photo for this challenge.  Overall I think it''s wonderful, it should definitely place highly :)', '2005-01-26 21:42:43.000000', NULL, 1),
(1134340, 138526, 10658, '<td valign="top">The lighting you used makes me want to "ooooh" and "aahhhh" :)  I even like the slight motion blur of his left hand.  Really cool photo!</td>', 'The lighting you used makes me want to "ooooh" and "aahhhh" :)  I even like the slight motion blur of his left hand.  Really cool photo!', '2005-01-26 21:45:09.000000', NULL, 1),
(1134344, 139100, 10658, '<td valign="top">I love the photo, the colors just pop out at the viewer.  The only thing I don''t like is that border, it''s overpowering.  Really nice image though.</td>', 'I love the photo, the colors just pop out at the viewer.  The only thing I don''t like is that border, it''s overpowering.  Really nice image though.', '2005-01-26 21:46:55.000000', NULL, 1),
(1134345, 138443, 15574, '<td valign="top">Is that a Zack Wylde guitar?  Sweet if it is...</td>', 'Is that a Zack Wylde guitar?  Sweet if it is...', '2005-01-26 21:48:17.000000', NULL, 1),
(1134347, 138814, 10658, '<td valign="top">That''s absolutely heartbreaking, especially today.  It fits the challenge well in my opinion and has a strong message at the same time.</td>', 'That''s absolutely heartbreaking, especially today.  It fits the challenge well in my opinion and has a strong message at the same time.', '2005-01-26 21:48:49.000000', NULL, 1),
(1134351, 139315, 15574, '<td valign="top">what in the world is this?</td>', 'what in the world is this?', '2005-01-26 21:54:47.000000', NULL, 1),
(1134354, 139077, 10658, '<td valign="top">First, I recommend that you try a larger image next time.  The crop is a bit too tight.  It''s a good idea, I mean poker is definitely "normal activity" (quoted from the challenge guidelines), but I think it could''ve been presented differently.  As it is this is a very average shot.</td>', 'First, I recommend that you try a larger image next time.  The crop is a bit too tight.  It''s a good idea, I mean poker is definitely "normal activity" (quoted from the challenge guidelines), but I think it could''ve been presented differently.  As it is this is a very average shot.', '2005-01-26 21:58:03.000000', NULL, 1),
(1134477, 138644, 24065, '<td valign="top">Oh, man!  Is this Giverny?  I am soooo jealous!  Great photo, too.  One of the best in the challenge.</td>', 'Oh, man!  Is this Giverny?  I am soooo jealous!  Great photo, too.  One of the best in the challenge.', '2005-01-26 23:30:40.000000', NULL, 1),
(1134688, 138260, 28268, '<td valign="top">beautiful</td>', 'beautiful', '2005-01-27 02:24:31.000000', NULL, 1),
(1134689, 139343, 28268, '<td valign="top">awesome</td>', 'awesome', '2005-01-27 02:24:50.000000', NULL, 1),
(1134736, 138739, 32746, '<td valign="top">absolutely beautiful :)</td>', 'absolutely beautiful :)', '2005-01-27 03:05:26.000000', NULL, 1),
(1134737, 138730, 9668, '<td valign="top">Nice use of trimary color. The yellow, green, and orange, all surrounded by white.</td>', 'Nice use of trimary color. The yellow, green, and orange, all surrounded by white.', '2005-01-27 03:05:46.000000', NULL, 1),
(1134740, 138606, 9668, '<td valign="top">I think the tilt in the horizon adds to the odd perspective of this photos. Nicely done</td>', 'I think the tilt in the horizon adds to the odd perspective of this photos. Nicely done', '2005-01-27 03:06:57.000000', NULL, 1),
(1134741, 139336, 21245, '<td valign="top">Hmm, this one isn''t getting the responses you''d hoped for eh?  Well, it''s not your best work Jon.  There''s not really anything wrong with it, but the angle of his pectoral muscle is somewhat androgynous, whereas the hairyness of his arms are inmistakably male, leaving the viewer unsure of how to feel about it.  That''s my $.02 anyhow.  I hope your scores improve, it''s a technically strong image, and artistically interesting, but it doesn''t speak to me like the hands and some of your other work does.</td>', 'Hmm, this one isn''t getting the responses you''d hoped for eh?  Well, it''s not your best work Jon.  There''s not really anything wrong with it, but the angle of his pectoral muscle is somewhat androgynous, whereas the hairyness of his arms are inmistakably male, leaving the viewer unsure of how to feel about it.  That''s my $.02 anyhow.  I hope your scores improve, it''s a technically strong image, and artistically interesting, but it doesn''t speak to me like the hands and some of your other work does.', '2005-01-27 03:07:18.000000', NULL, 1),
(1134745, 137504, 21245, '<td valign="top">Huh?  Some blurry shot of the back of someone''s head?.... I jest, I recognize your style, and I like this one, great sense of motion and color 9</td>', 'Huh?  Some blurry shot of the back of someone''s head?.... I jest, I recognize your style, and I like this one, great sense of motion and color 9', '2005-01-27 03:10:12.000000', NULL, 1),
(1134852, 138743, 25355, '<td valign="top">Clever, but there needs to be an actual human in the photo, and I can''t see one.</td>', 'Clever, but there needs to be an actual human in the photo, and I can''t see one.', '2005-01-27 05:37:40.000000', NULL, 1),
(1134907, 138743, 23458, '<td valign="top">Think you''ve hit the DPC formula on the head with this one :). <br/> <br/>Fantastic Image - I''m sure some will complain about the uneven colouration on the wall, but for mine it adds a little something - some character to the image.</td>', 'Think you''ve hit the DPC formula on the head with this one :).  Fantastic Image - I''m sure some will complain about the uneven colouration on the wall, but for mine it adds a little something - some character to the image.', '2005-01-27 06:54:45.000000', NULL, 1),
(1134909, 138184, 29477, '<td valign="top">My Guess - xtabintun</td>', 'My Guess - xtabintun', '2005-01-27 06:56:12.000000', NULL, 1),
(1134921, 138228, 3306, '<td valign="top">This is a good good well thought out shot. I like the lighting on the face  that creates the image in the mirror. The picture m akes me feel like I am right in the bathroom with him (now that''s a scary thought!) Well done.</td>', 'This is a good good well thought out shot. I like the lighting on the face  that creates the image in the mirror. The picture m akes me feel like I am right in the bathroom with him (now that''s a scary thought!) Well done.', '2005-01-27 07:15:12.000000', NULL, 1),
(1134923, 138747, 3306, '<td valign="top">I predict his ball is going to  slice,  hit that tree on the right and bounce right into the middle of the fairway!</td>', 'I predict his ball is going to  slice,  hit that tree on the right and bounce right into the middle of the fairway!', '2005-01-27 07:17:58.000000', NULL, 1),
(1134928, 138966, 3306, '<td valign="top">Very creative and original.  I hope you have one of these with the model''s head in it. Too bad it had to be cropped like this for the challenge. You should keep working with this idea as it has many interesting and creative  possibilities.</td>', 'Very creative and original.  I hope you have one of these with the model''s head in it. Too bad it had to be cropped like this for the challenge. You should keep working with this idea as it has many interesting and creative  possibilities.', '2005-01-27 07:21:28.000000', NULL, 1),
