(1134997, 138184, 30173, '<td valign="top">Good idea and well performed.</td>', 'Good idea and well performed.', '2005-01-27 08:48:52.000000', NULL, 1),
(1135232, 138966, 26505, '<td valign="top">I really think this is a cool shot.  I think you got pretty creative with the background.  Im not really digging the fact that she is vacuming rocks.  I do get that it is "stepping out of the box", but I think I would rather see her in a setting that actually needs vacuming.  Of course that is just a housewife''s point of view.  But the overall image is really great.  I am going to give it a 9.</td>', 'I really think this is a cool shot.  I think you got pretty creative with the background.  Im not really digging the fact that she is vacuming rocks.  I do get that it is "stepping out of the box", but I think I would rather see her in a setting that actually needs vacuming.  Of course that is just a housewife''s point of view.  But the overall image is really great.  I am going to give it a 9.', '2005-01-27 13:10:31.000000', NULL, 1),
(1135268, 139215, 30818, '<td valign="top">very funny...  but a bit too grainy</td>', 'very funny...  but a bit too grainy', '2005-01-27 13:37:27.000000', NULL, 1),
