(1135582, 139257, 32702, '<td valign="top">Very interresting composition.  Nice colours.  Could be little sharper but on the otherhand it actually works for this picture.</td>', 'Very interresting composition.  Nice colours.  Could be little sharper but on the otherhand it actually works for this picture.', '2005-01-27 17:52:47.000000', NULL, 1),
(1135602, 137504, 32702, '<td valign="top">Very, very, very interresting picture... Nice colour, could have used higher shutterspeed, but then I am probably missing the point, but I really see and feel the motion in this picture.</td>', 'Very, very, very interresting picture... Nice colour, could have used higher shutterspeed, but then I am probably missing the point, but I really see and feel the motion in this picture.', '2005-01-27 17:59:36.000000', NULL, 1),
(1135614, 139063, 32702, '<td valign="top">Nice colours.<br/>Seems to be little lacking in the sharpness department, but it could be the resize.<br/>Subject is a little bit uninterresting.<br/>There is way too much in the background.</td>', 'Nice colours.Seems to be little lacking in the sharpness department, but it could be the resize.Subject is a little bit uninterresting.There is way too much in the background.', '2005-01-27 18:03:14.000000', NULL, 1),
(1135621, 138575, 32702, '<td valign="top">I would have cropped out the bird and made it a wider and tighter composition, otherwise it  is pretty nice.</td>', 'I would have cropped out the bird and made it a wider and tighter composition, otherwise it  is pretty nice.', '2005-01-27 18:05:13.000000', NULL, 1),
(1135628, 139220, 32702, '<td valign="top">Excellent, This is a very impressing picture.  Nice contrast and sharpness.</td>', 'Excellent, This is a very impressing picture.  Nice contrast and sharpness.', '2005-01-27 18:06:44.000000', NULL, 1),
(1135631, 139099, 32702, '<td valign="top">This picture is a little bit dull to my eyes, could have used bit more saturation.</td>', 'This picture is a little bit dull to my eyes, could have used bit more saturation.', '2005-01-27 18:09:09.000000', NULL, 1),
(1135644, 137441, 32702, '<td valign="top">Colours are bit strange, but I like them... Noise levels are little high, but work well here.<br/>Left hand distracts me a little bit.</td>', 'Colours are bit strange, but I like them... Noise levels are little high, but work well here.Left hand distracts me a little bit.', '2005-01-27 18:12:53.000000', NULL, 1),
