(1135943, 138280, 32033, '<td valign="top">I would have rather been looking at a woman window shopping.  Nice picture</td>', 'I would have rather been looking at a woman window shopping.  Nice picture', '2005-01-27 20:19:04.000000', NULL, 1),
(1135945, 139350, 32033, '<td valign="top">I like the picture although it gives me the feeling he is about to get lost.</td>', 'I like the picture although it gives me the feeling he is about to get lost.', '2005-01-27 20:20:44.000000', NULL, 1),
(1136122, 139321, 31505, '<td valign="top">is that me</td>', 'is that me', '2005-01-27 22:09:55.000000', NULL, 1),
