(1136148, 138880, 1031, '<td valign="top">Somehow I don''t think I''d recommend this as an "everyday" activity.</td>', 'Somehow I don''t think I''d recommend this as an "everyday" activity.', '2005-01-27 22:39:30.000000', NULL, 1),
(1136150, 137506, 1031, '<td valign="top">I hope not for simultaneous use!</td>', 'I hope not for simultaneous use!', '2005-01-27 22:40:50.000000', NULL, 1),
(1136159, 138009, 1031, '<td valign="top">Nice collection of shapes and angles here.</td>', 'Nice collection of shapes and angles here.', '2005-01-27 22:50:37.000000', NULL, 1),
(1136168, 139215, 28695, '<td valign="top">Ok.  That made me laugh.  I was gonna mark you down for graininess, but, while laughing, I saw that it was intentional (I think).  I think it fits the mood and humor of the picture.</td>', 'Ok.  That made me laugh.  I was gonna mark you down for graininess, but, while laughing, I saw that it was intentional (I think).  I think it fits the mood and humor of the picture.', '2005-01-27 23:05:56.000000', NULL, 1),
