(1136351, 138182, 30490, '<td valign="top">I love the clarity of this photo and the texture of the hair and sweater</td>', 'I love the clarity of this photo and the texture of the hair and sweater', '2005-01-28 01:02:50.000000', NULL, 1),
(1136355, 139336, 30490, '<td valign="top">Great color contrast in the flesh tone and the green tile.  I wish the hand was a little sharper / more focused.</td>', 'Great color contrast in the flesh tone and the green tile.  I wish the hand was a little sharper / more focused.', '2005-01-28 01:06:16.000000', NULL, 1),
(1136357, 139326, 30490, '<td valign="top">I love the effect of the light/dark in this photo.</td>', 'I love the effect of the light/dark in this photo.', '2005-01-28 01:07:57.000000', NULL, 1),
(1136360, 138617, 30490, '<td valign="top">Cool, crisp and compelling!</td>', 'Cool, crisp and compelling!', '2005-01-28 01:08:41.000000', NULL, 1),
(1136362, 138569, 30490, '<td valign="top">This seems so ordinary but is yet compelling.  Nice image</td>', 'This seems so ordinary but is yet compelling.  Nice image', '2005-01-28 01:09:14.000000', NULL, 1),
(1136363, 139080, 30490, '<td valign="top">I feel like I am running behind them!  Great shot!</td>', 'I feel like I am running behind them!  Great shot!', '2005-01-28 01:09:46.000000', NULL, 1),
(1136367, 138644, 30490, '<td valign="top">Looking at the individual aspects of this photo, the green countryside, a man on a bench, a hazy sky this photo should be ordinary, but yet, I find it mysterious and compelling when combined into this one image.</td>', 'Looking at the individual aspects of this photo, the green countryside, a man on a bench, a hazy sky this photo should be ordinary, but yet, I find it mysterious and compelling when combined into this one image.', '2005-01-28 01:11:39.000000', NULL, 1),
(1136369, 139229, 30490, '<td valign="top">Scary but cool.  Great idea and execution!  I hope not to run into this guy in my dark closet any night soon!</td>', 'Scary but cool.  Great idea and execution!  I hope not to run into this guy in my dark closet any night soon!', '2005-01-28 01:12:39.000000', NULL, 1),
