(1138143, 137427, 25464, '<td valign="top">This gorgeous photo I fear will suffer due to the unlevel horizon.  Had that been fixed, I think this would have been the winner.  Best of luck.</td>', 'This gorgeous photo I fear will suffer due to the unlevel horizon.  Had that been fixed, I think this would have been the winner.  Best of luck.', '2005-01-29 01:16:56.000000', NULL, 1),
(1138144, 139232, 25464, '<td valign="top">Nice composition.  I love the kicked up snow and the contrast of the bright red coat.</td>', 'Nice composition.  I love the kicked up snow and the contrast of the bright red coat.', '2005-01-29 01:18:06.000000', NULL, 1),
(1138145, 139100, 25464, '<td valign="top">I love what you did with the colors here.  The composition is a bit strange, but it works for me.  Good luck.</td>', 'I love what you did with the colors here.  The composition is a bit strange, but it works for me.  Good luck.', '2005-01-29 01:18:49.000000', NULL, 1),
(1138147, 138084, 25464, '<td valign="top">Great capture of excitement and curiosity in the posture of the boys.  It looks a little over processed to me, but not enough to hurt my scoring.  Very nice.</td>', 'Great capture of excitement and curiosity in the posture of the boys.  It looks a little over processed to me, but not enough to hurt my scoring.  Very nice.', '2005-01-29 01:20:13.000000', NULL, 1),
(1138153, 138644, 25464, '<td valign="top">Very nice background.  Great detail on the bench.  The only thing that bothers me about this one is the color of the coat.  It looks to me like it is supposed to be a beige trench coat sort of jacket, but it looks pink.  I suspect the colors were modified to get the best background result, but I think the coat took a hit in the process.  That said, I still gave it a 10.</td>', 'Very nice background.  Great detail on the bench.  The only thing that bothers me about this one is the color of the coat.  It looks to me like it is supposed to be a beige trench coat sort of jacket, but it looks pink.  I suspect the colors were modified to get the best background result, but I think the coat took a hit in the process.  That said, I still gave it a 10.', '2005-01-29 01:22:56.000000', NULL, 1),
(1138154, 139080, 25464, '<td valign="top">This is my favorite of the challenge.  The action, light, and tones are perfect.  My black and white shots are never this dramatic.  Great job.</td>', 'This is my favorite of the challenge.  The action, light, and tones are perfect.  My black and white shots are never this dramatic.  Great job.', '2005-01-29 01:24:22.000000', NULL, 1),
(1138156, 139357, 25464, '<td valign="top">Beautiful colors.  Nice reflections.</td>', 'Beautiful colors.  Nice reflections.', '2005-01-29 01:25:23.000000', NULL, 1),
(1138159, 138916, 25464, '<td valign="top">This is a beautiful sky.  The light is great.  The composition is a little off IMO.  The OOF grass blades in the foreground are distracting, and the couple is perhaps a bit too centered.  Still one of my top picks.</td>', 'This is a beautiful sky.  The light is great.  The composition is a little off IMO.  The OOF grass blades in the foreground are distracting, and the couple is perhaps a bit too centered.  Still one of my top picks.', '2005-01-29 01:27:14.000000', NULL, 1),
(1138161, 138312, 25464, '<td valign="top">Simple, classic.  Nice tones and detail.  A top 10 pick for me.</td>', 'Simple, classic.  Nice tones and detail.  A top 10 pick for me.', '2005-01-29 01:28:11.000000', NULL, 1);
