(1138172, 138617, 27812, '<td valign="top">Great action shot.. how do you set up for that? 10</td>', 'Great action shot.. how do you set up for that? 10', '2005-01-29 01:35:44.000000', NULL, 1),
(1138173, 138903, 25464, '<td valign="top">This photo brings back memories of watching horse and elephant training in the big barns at the circus winter quarters as a kid. Great shot and thanks for the lovely memory.  A new favorite for me.</td>', 'This photo brings back memories of watching horse and elephant training in the big barns at the circus winter quarters as a kid. Great shot and thanks for the lovely memory.  A new favorite for me.', '2005-01-29 01:35:49.000000', NULL, 1),
