(1140062, 138431, 7910, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2005-01-30 11:46:50.000000', NULL, 1),
(1140066, 137427, 7910, '<td valign="top">Ok, add one more person complaining about the crooked horizon.  Other than that, nice colors.</td>', 'Ok, add one more person complaining about the crooked horizon.  Other than that, nice colors.', '2005-01-30 11:49:48.000000', NULL, 1),
(1140069, 139215, 7910, '<td valign="top">Well at least mine isn''t the only one.</td>', 'Well at least mine isn''t the only one.', '2005-01-30 11:51:26.000000', NULL, 1),
(1140138, 139315, 2158, '<td valign="top">Deleted - comment accidentally inserted for wrong picture.<br/><br/><i>Message edited by author 2005-01-31 05:54:33.</i></td>', 'Deleted - comment accidentally inserted for wrong picture.', '2005-01-30 12:29:29.000000', '2005-01-31 05:54:33.000000', 1),
(1140142, 139290, 10818, '<td valign="top">Hah, very funny, well done photo.  Great job finding fresh snow and not stomping in it setting it up.</td>', 'Hah, very funny, well done photo.  Great job finding fresh snow and not stomping in it setting it up.', '2005-01-30 12:40:01.000000', NULL, 1),
(1140143, 138575, 10818, '<td valign="top">Beautiful photo.  Wonderful job with the pier, pretty clouds and the seagull is a great bonus.</td>', 'Beautiful photo.  Wonderful job with the pier, pretty clouds and the seagull is a great bonus.', '2005-01-30 12:43:12.000000', NULL, 1),
(1140147, 138922, 10818, '<td valign="top">Wonderful photo.  Beautiful town,  you captured the couple perfecly.</td>', 'Wonderful photo.  Beautiful town,  you captured the couple perfecly.', '2005-01-30 12:51:13.000000', NULL, 1),
(1140149, 137427, 10818, '<td valign="top">Beautiful sunset, warm rich colors...lovely.  Its a tad tilted, but not too bad.<br/> <br/>Great shot.</td>', 'Beautiful sunset, warm rich colors...lovely.  Its a tad tilted, but not too bad. Great shot.', '2005-01-30 12:54:02.000000', NULL, 1),
(1140150, 139080, 10818, '<td valign="top">Great composition, looks  great in B &amp; W....steam really adds to the photo.</td>', 'Great composition, looks  great in B & W....steam really adds to the photo.', '2005-01-30 12:56:56.000000', NULL, 1),
(1140155, 139232, 10818, '<td valign="top">Great action shot, snow looks awesome.</td>', 'Great action shot, snow looks awesome.', '2005-01-30 13:02:45.000000', NULL, 1),
(1140157, 139215, 10818, '<td valign="top">Hah, that is freaking hilarious .  Well done shot that gets across the point real well.</td>', 'Hah, that is freaking hilarious .  Well done shot that gets across the point real well.', '2005-01-30 13:05:15.000000', NULL, 1),
(1140159, 138338, 10818, '<td valign="top">Very subtle shot, took me a few second.<br/> <br/>Super photo.</td>', 'Very subtle shot, took me a few second. Super photo.', '2005-01-30 13:12:15.000000', NULL, 1),
(1140165, 138763, 10818, '<td valign="top">The kids body language really makes this shot.   Fabulous job catching this as the shark is passing by.</td>', 'The kids body language really makes this shot.   Fabulous job catching this as the shark is passing by.', '2005-01-30 13:16:38.000000', NULL, 1),
(1140218, 138916, 6008, '<td valign="top">The grad filter looks a little strong but it helps create the monochromatic feel to the image. I like the framing of the couple and the kiss of light on the side of their heads.</td>', 'The grad filter looks a little strong but it helps create the monochromatic feel to the image. I like the framing of the couple and the kiss of light on the side of their heads.', '2005-01-30 14:33:17.000000', NULL, 1),
(1140225, 138860, 6008, '<td valign="top">I like the diagonal lines created by the sand, the water line, and the foam. The light is a little even and flat, though, and the image could do with a little boost in saturation and contrast. Overall the image quality looks a little off as if digital zoom was used.</td>', 'I like the diagonal lines created by the sand, the water line, and the foam. The light is a little even and flat, though, and the image could do with a little boost in saturation and contrast. Overall the image quality looks a little off as if digital zoom was used.', '2005-01-30 14:42:07.000000', NULL, 1),
(1140266, 139248, 12421, '<td valign="top">Straightening the horizon would really help in this picture.</td>', 'Straightening the horizon would really help in this picture.', '2005-01-30 15:05:56.000000', NULL, 1),
(1140334, 138814, 13536, '<td valign="top">I really find this offensive at this time!</td>', 'I really find this offensive at this time!', '2005-01-30 15:42:33.000000', NULL, 1),
(1140347, 138891, 32111, '<td valign="top">Que?</td>', 'Que?', '2005-01-30 15:56:21.000000', NULL, 1),
