(1141773, 139080, 14614, '<td valign="top">Congrats Jon!  Lovely image that tells a great story,  steam makes the shot!</td>', 'Congrats Jon!  Lovely image that tells a great story,  steam makes the shot!', '2005-01-31 06:58:54.000000', NULL, 0),
